create unique index if not exists "IX_Employees_Employee #"
    on public."Employees" ("Employee #");

create unique index if not exists "IX_Employers_RP#"
    on public."Employers" ("RP#");

create unique index if not exists "IX_Calculations_Name"
    on public."Calculations" ("Name");

create index if not exists "IX_PayrollRecords_Employee #"
    on public."PayrollRecords" ("Employee #");

create index if not exists "IX_PayrollRecords_RP#"
    on public."PayrollRecords" ("RP#");

create index if not exists "IX_Record History_Employee #"
    on public."Record History" ("Employee #");

create index if not exists "IX_Record History_RP#"
    on public."Record History" ("RP#");

create index if not exists "IX_Record History_Year_Month"
    on public."Record History" ("Year", "Month");

do $$
begin
    if not exists (
        select 1
        from pg_constraint
        where conname = 'FK_PayrollRecords_Employees_Employee #'
    ) then
        alter table public."PayrollRecords"
            add constraint "FK_PayrollRecords_Employees_Employee #"
            foreign key ("Employee #")
            references public."Employees" ("Employee #")
            on delete cascade;
    end if;

    if not exists (
        select 1
        from pg_constraint
        where conname = 'FK_PayrollRecords_Employers_RP#'
    ) then
        alter table public."PayrollRecords"
            add constraint "FK_PayrollRecords_Employers_RP#"
            foreign key ("RP#")
            references public."Employers" ("RP#")
            on delete cascade;
    end if;
end $$;

commit;
